def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Find diagonal pairs of 1s and fill the segment joining them.
    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr != 0 and abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                cells = []
                r, c = r1, c1
                while True:
                    cells.append((r, c))
                    if (r, c) == (r2, c2):
                        break
                    r += sr
                    c += sc
                segments.append((sr, sc, set(cells)))
                for r, c in cells:
                    if out[r][c] != 6:
                        out[r][c] = 1

    # A 6 on a connecting segment extends along the perpendicular diagonal.
    for sr, sc, cells in segments:
        for r0, c0 in sixes:
            if (r0, c0) not in cells:
                continue
            for sign in (-1, 1):
                r, c = r0 + sign * sr, c0 - sign * sc
                while 0 <= r < h and 0 <= c < w:
                    if out[r][c] != 1:
                        out[r][c] = 6
                    r += sign * sr
                    c -= sign * sc

    return out
